export function futureIntegrations(){return `<section class="future-integrations" aria-label="Future integration concepts"><div><span class="eyebrow">Looking ahead</span><p>More ways to bring your money into view.</p></div><ul>${[['SBI','S','bank'],['HDFC Bank','H','bank'],['Google Pay','G','upi'],['PhonePe','P','upi']].map(([name,letter,type])=>`<li><span class="integration-icon ${type}" aria-hidden="true">${letter}</span><span>${name}<small>${type==='bank'?'Bank':'UPI app'}</small></span></li>`).join('')}</ul><p class="integration-note">Future integration concepts · Not connected or affiliated. Icons are illustrative placeholders.</p></section>`;}
